import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import { CircleCheck, UserRound } from "lucide-react";
import { useAuthState } from "../hooks/useAuth";
import { loadReports } from "../lib/reports";
import { firstName } from "../lib/report";
import ReportView from "../components/report/ReportView";
import DownloadReportButton from "../components/report/DownloadReportButton";

// Shows the report just generated by the quiz (passed in router state),
// or otherwise the latest report saved to the account
const Result = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, ready } = useAuthState();
  const [entry, setEntry] = useState(location.state?.entry || null);
  const [saved, setSaved] = useState(location.state?.saved ?? true);
  const [status, setStatus] = useState(location.state?.entry ? "ready" : "loading");

  useEffect(() => {
    if (!ready) return;
    if (!user) {
      toast.info("Sign in to see your career report.");
      navigate("/login");
      return;
    }
    if (location.state?.entry) return;

    let cancelled = false;
    (async () => {
      try {
        // Left over from the old quiz flow, which kept the report only in the browser
        localStorage.removeItem("suggestions");

        const { reports } = await loadReports(user.uid);
        if (cancelled) return;
        setEntry(reports[0] || null);
        setSaved(true);
        setStatus(reports[0] ? "ready" : "empty");
      } catch (error) {
        console.error("Couldn't load the career report:", error);
        if (!cancelled) setStatus("error");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [ready, user, navigate, location.state]);

  useEffect(() => {
    window.scrollTo({ top: 0 });
  }, []);

  const name = firstName(user);

  return (
    <main className="min-h-[calc(100vh-4rem)] bg-surface px-4 py-6 sm:px-6 sm:py-10">
      <div className="mx-auto max-w-5xl">
        {status === "loading" && (
          <p className="card-shadow rounded-3xl bg-white p-10 text-center text-ink-soft" role="status">
            Loading your career report...
          </p>
        )}

        {(status === "empty" || status === "error") && (
          <div className="card-shadow mx-auto max-w-xl rounded-3xl bg-white p-10 text-center">
            <img src="/images/trophy.webp" alt="" className="mx-auto h-24 w-24 object-contain" />
            <h1 className="mt-5 text-2xl font-extrabold tracking-tight text-ink">
              {status === "empty" ? "No career report yet" : "We couldn't load your report"}
            </h1>
            <p className="mt-2 text-ink-soft">
              {status === "empty"
                ? "Take the career quiz and your guides will write one for you."
                : "Check your connection and try again."}
            </p>
            <button
              onClick={() => (status === "empty" ? navigate("/quiz") : window.location.reload())}
              className="btn-primary mt-7 px-6 py-3"
            >
              {status === "empty" ? "Take the career quiz" : "Try again"}
            </button>
          </div>
        )}

        {status === "ready" && entry && (
          <>
            {location.state?.entry && (
              <div
                role="status"
                className={`mb-4 flex items-center gap-2.5 rounded-2xl px-4 py-3 text-sm font-semibold ${
                  saved ? "bg-mint text-ink" : "bg-butter text-ink"
                }`}
              >
                <CircleCheck className={`h-5 w-5 shrink-0 ${saved ? "text-[#2F9E78]" : "text-accent"}`} aria-hidden="true" />
                {saved
                  ? "Your report is ready and saved to your profile."
                  : "Your report is ready, but we couldn't save it to your profile. Download the PDF to keep it."}
              </div>
            )}
            <ReportView
              report={entry.report}
              name={name}
              createdAt={entry.createdAt}
              workStyles={entry.workStyles}
              actions={
                <>
                  <DownloadReportButton user={user} entry={entry} name={name} />
                  <Link to="/profile" className="btn-outline px-6 py-3">
                    <UserRound className="h-4 w-4" aria-hidden="true" />
                    View in profile
                  </Link>
                </>
              }
            />
          </>
        )}
      </div>
    </main>
  );
};

export default Result;
